'use strict';
const D=window.PRAPJ_DOCUMENTS,J=window.PRAPJ_CONTENT.journal,G=window.PRAPJ_CONTENT.governance,B=window.PRAPJ_CONTENT.business;
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const doc=id=>D.find(d=>d.id===id);
function ref(id,part=''){const d=doc(id),s=d.sections.find(s=>s.title.toLowerCase().includes(part.toLowerCase()));return `#/document/${id}${part&&s?'/'+s.id:''}`}
function source(id,part,label){return `<small class="source">Source: <a href="${ref(id,part)}">${e(label||doc(id).title+(part?' · '+part:''))} ↗</a></small>`}
const button=(text,url,secondary=false)=>`<a class="button${secondary?' secondary':''}" href="${url}">${e(text)} <span aria-hidden="true">↗</span></a>`;
const link=(text,url)=>`<a class="text-link" href="${url}">${e(text)} ↗</a>`;
const notice=(title,text,kind='')=>`<div class="notice ${kind}"><strong>${e(title)}</strong>${e(text)}</div>`;
const list=items=>`<ul class="list-clean">${items.map(x=>`<li>${e(x)}</li>`).join('')}</ul>`;
const table=(heads,rows)=>`<div class="table-scroll" tabindex="0" role="region" aria-label="${e(heads.join(', '))}"><table><thead><tr>${heads.map(x=>`<th scope="col">${e(x)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(x=>`<td>${e(x)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
const details=(title,body)=>`<details><summary>${e(title)}</summary><div class="detail-body">${body}</div></details>`;
const pageTop=(label,title,intro,extra='')=>`<section class="wrap page-top"><span class="eyebrow">${e(label)}</span><h1>${e(title)}</h1><p class="intro">${e(intro)}</p>${extra}</section>`;
function heading(k,title,text=''){return `<div class="section-head"><div><span class="eyebrow">${e(k)}</span><h2>${e(title)}</h2></div>${text?`<p>${e(text)}</p>`:''}</div>`}
let activeMode='journal';
const journalNav=[['journal','Overview'],['about','About & scope'],['authors','For authors'],['review','Review & ethics'],['templates','Templates'],['publications','Articles & collections']];
const projectNav=[['project','Project overview'],['case','Business case'],['governance','Governance'],['delivery','Delivery & risks'],['specimen','Journal design'],['handoff','Website handoff']];
const descriptions=['The strategic case, four interview accounts, option appraisal, hypothetical resources and readiness gates.','Separate board responsibilities, independent decisions and prospective invitation pools.','Contribution formats, manuscript requirements, ethics, preparation and publication.','Assessment routes, service targets, decisions, integrity and continuity.','The journal proposition, publishing information, proposed access and author support.','Page copy, current function states, content owners and release conditions.','Fourteen blank author, reviewer, production and governance forms.','A hardcopy design specimen with clearly labelled illustrative content.'];
function home(){return `<section class="wrap hero"><div><span class="eyebrow">Project Research and Practice Journal</span><h1>Evidence for<br><em>project decisions.</em></h1><p class="intro">A proposed journal connecting credible research, professional judgement and practical experience. Understand what the evidence says — and where its limits begin.</p><div class="actions">${button('Prepare a contribution','#/authors')}${button('Explore the project','#/project',true)}</div><div style="margin-top:26px"><span class="status-pill">In development · submissions not open</span></div></div><div class="hero-art"><span class="art-label">RESEARCH ↔ PRACTICE</span><img src="assets/journal-cover.png" alt="PRAPJ pre-publication cover concept, with architectural forms joined by a bridge"><div class="floating-note"><strong>From evidence<br>to judgement.</strong>Find the decision.<br>Inspect the evidence.<br>Check the conditions.</div><span class="cover-caption">Pre-publication cover concept</span></div></section><section class="stat-strip"><div class="wrap"><div class="stat"><b>04</b><span>Core contribution routes<br>One coherent journal model</span></div><div class="stat"><b>↔</b><span>Research informs practice<br>Practice shapes questions</span></div><div class="stat"><b>Open</b><span>Diamond access preferred<br>Support & adoption pending</span></div></div></section><section class="wrap">${heading('A place for different kinds of evidence','Choose the form your evidence needs.','Four core routes, with standards matched to the contribution. Evidence Reviews sit within the research track.') }<div class="grid four">${[{i:0,n:'Research',copy:'Develop and test knowledge with transparent methods, evidence and practical implications.'},{i:2,n:'Practitioner Cases',copy:'Explain a real decision, its outcomes, and the conditions for transferring a lesson.'},{i:3,n:'Research-to-Practice Briefs',copy:'Translate identifiable source research into useful, bounded professional questions.'},{i:4,n:'Challenges & Evidence Notes',copy:'Bring focused evidence and unresolved problems into the research conversation.'}].map((x,i)=>`<a class="route-card" href="#/authors/${J.contribution_specification.types[x.i].id}"><span class="n">0${i+1}</span><h3>${x.n}</h3><p>${x.copy}</p><div class="card-bottom"><span>${J.contribution_specification.types[x.i].main_words.map(n=>n.toLocaleString()).join('–')} words${i===0?'*':''}</span><span>↗</span></div></a>`).join('')}</div><p class="small muted" style="margin-top:16px">*Research Article range. Evidence Reviews: 5,000–8,000 words. All specifications are proposed.</p>${source('03','1 Aims')}</section><section class="pale"><div class="wrap split"><div><span class="eyebrow">Designed for professional judgement</span><h2>Read with a decision in mind.</h2><p class="muted">The initial audience is experienced and mid-career project professionals, alongside researchers and educators.</p>${link('Explore the aims and scope','#/about')}</div><div class="steps"><div class="step"><div><h3>Recognise the decision</h3><p>Start with the project objective, problem, alternatives and relevant setting.</p></div></div><div class="step"><div><h3>Inspect the evidence</h3><p>See the method, source and uncertainty. Separate findings from interpretation.</p></div></div><div class="step"><div><h3>Judge where it applies</h3><p>Identify a proportionate action and the conditions that could limit its usefulness.</p></div></div></div></div></section><section class="wrap">${heading('Explore further','A journal and the case behind it.')}<div class="grid two"><div class="statement"><p>Prepare your work with transparent requirements and editable templates.</p><div class="actions">${link('Open the author guide','#/authors')}${link('Browse 14 templates','#/templates')}</div></div><div class="statement"><p>Examine the evidence, governance and resources needed to establish PRAPJ.</p><div class="actions">${link('Read the business case','#/case')}${link('Explore all 8 documents','#/library')}</div></div></div></section>`}
function about(){return pageTop('The journal · Aims and scope','Research and practice, in both directions.',J.scope_and_audience.scope)+`<section class="wrap split"><div><span class="eyebrow">Who it is for</span><h2>Professional decisions.<br>Credible contribution.</h2><p class="lead">${e(J.scope_and_audience.primary)}</p><p class="muted">Researchers and educators are part of the exchange. Accessible explanations for students and emerging professionals may follow.</p>${source('05','About')}</div><div>${list(J.scope_and_audience.evidence_principles)}${notice('Outside the proposed scope',J.scope_and_audience.outside_scope)}</div></section><section class="pale"><div class="wrap">${heading('Areas of inquiry','Project knowledge across settings.')}<div class="tag-row">${J.scope_and_audience.topics.map(x=>`<span class="tag">${e(x)}</span>`).join('')}</div><p class="muted" style="max-width:780px;margin-top:24px">From infrastructure and technology to healthcare and public administration: contributions should explain what is comparable across settings and what is not.</p></div></section><section class="wrap">${heading('The proposed publication model','Open access, with responsibilities made clear.')}<div class="grid three">${[['Digital first','Articles would publish as ready, with two curated collections each year.'],['Diamond open access','No submission fee, APC or reader paywall under the preferred model, subject to confirmed support and adoption.'],['Author rights','CC BY 4.0 and author-retained copyright are proposed. Final terms need a publisher-approved agreement.']].map(([t,p])=>`<div class="route-card"><h3>${t}</h3><p>${p}</p></div>`).join('')}</div>${source('05','Publish open access')}<div class="accordion" style="margin-top:38px">${details('Editorial independence',`<p>${e(G.journal_governance.independence_copy)}</p>${link('Explore governance roles','#/governance')}`)}${details('Sharing, preprints and the published record',`<p>${e(J.access_and_rights.sharing)}</p>${source('05','Publish sharing')}`)}${details('What is still to be confirmed',table(['Journal information','Current status'],[['Publisher and host','To be confirmed'],['Editorial appointments','No accepted appointments announced'],['Launch date and submission portal','To be confirmed; submissions remain closed'],['ISSN, DOI and preservation','Arrangements to be confirmed'],['Indexing and publication metrics','No confirmed inclusion or verified publication history'],['Editorial, technical and appeals contacts','Official channels will be published after appointment']]))}</div></section>`}
function authorPage(type='research'){const t=J.contribution_specification.types.find(x=>x.id===type)||J.contribution_specification.types[0];return pageTop('For authors · Proposed guide v1.3','Start with the evidence you have.','Choose your contribution format, see the preparation requirements and work through the checklist. The proposed guide remains subject to editorial adoption.',`<span class="status-pill">Submissions are not yet open</span>`)+`<section class="wrap">${heading('01 / Choose a format','A route for your contribution.')}<div class="tabs" aria-label="Contribution format">${J.contribution_specification.types.map(x=>`<button data-format="${x.id}" aria-pressed="${t.id===x.id}">${e(x.name)}</button>`).join('')}</div><div class="format-panel"><div class="format-description"><span class="eyebrow">${e(t.relationship)}</span><h2>${e(t.name)}</h2><p>${e(t.purpose)}</p>${t.structure?`<p class="small muted">Suggested structure</p><div class="tag-row">${t.structure.map(x=>`<span class="tag">${e(x)}</span>`).join('')}</div>`:''}</div><div class="format-specs"><div class="spec"><span class="value">${t.main_words.map(n=>n.toLocaleString()).join('–')}</span><span class="label">Main-text words</span></div><div class="spec"><span class="value">${t.summary_words?t.summary_words.join('–'):'By agreement'}</span><span class="label">${t.summary_words?e(t.summary_label)+' words':'Summary confirmed by commissioning editor'}</span></div><div class="spec"><span class="value">${t.decision_relevance_words?t.decision_relevance_words.join('–'):'By agreement'}</span><span class="label">Decision-relevance statement${t.decision_relevance_words?' words':''}</span></div><div class="spec"><span class="value">${t.keywords?t.keywords.join('–'):'By agreement'}</span><span class="label">Keywords</span></div><div class="spec full"><span class="label">Proposed assessment route</span><span class="value">${e(t.assessment)}</span></div></div></div>${source('03','1 Aims','Guide for Authors · §§1–3 & 9')}<div class="accordion" style="margin-top:24px">${details('What counts toward the word limit?',`<div class="grid two"><div><h4>Include</h4>${list(J.contribution_specification.word_count_includes)}</div><div><h4>Exclude</h4>${list(J.contribution_specification.word_count_excludes)}</div></div><p style="margin-top:20px">${e(J.contribution_specification.count_rules)}</p>`)}${details('Linked briefs, teaching cases and supported contributions',`<p>${e(J.research_summary_series.linked_brief_policy)}</p><p>${e(J.contribution_specification.teaching_cases)}</p><p>Interview support and optional media are being explored. They need confirmed capacity, source checks, permission, credited assistance and independent assessment.</p>${link('View support and media forms','#/templates/Supported contribution')}`)}</div></section><section class="pale"><div class="wrap split"><div><span class="eyebrow">02 / Prepare the package</span><h2>Separate identity<br>from the review file.</h2><p>${e(J.author_workflow.manuscript_format)}</p><div class="actions">${button('Browse manuscript templates','#/templates')}</div>${source('03','8 Manuscript')}</div><div class="accordion">${J.author_workflow.required_package.map(x=>details(x.item,`<p>${e(x.contents)}</p>`)).join('')}</div></div></section><section class="wrap split"><div><span class="eyebrow">03 / Check readiness</span><h2>A final check before submission opens.</h2><p class="muted">This checklist is a reading aid. It does not transmit files, certify readiness or submit a manuscript.</p><p class="small muted">Selections remain only while this page is open.</p>${source('03','12 Submission')}</div><div><div class="check-progress"><strong id="check-count">0 of ${J.author_workflow.final_checklist.length} checked</strong><button data-reset-checks>Reset</button></div><div class="progress-track"><div class="progress-fill" id="check-fill" style="width:0"></div></div><ul class="checklist">${J.author_workflow.final_checklist.map((x,i)=>`<li><label><input type="checkbox" data-check="${i}"><span>${e(x)}</span></label></li>`).join('')}</ul></div></section><section class="wrap" style="padding-top:0">${heading('04 / Keep the policy detail close','Ethics, preparation and publication.')}<div class="accordion">${[['Authorship, interests and prior versions',J.review_and_ethics.authorship+' '+J.review_and_ethics.originality],['Research ethics and permissions',J.review_and_ethics.human_ethics+' '+J.review_and_ethics.case_permissions],['Generative AI and evidence integrity',J.review_and_ethics.author_ai+' '+J.review_and_ethics.ai_and_evidence],['Anonymous preparation',J.author_workflow.anonymous_preparation],['Data and references',J.review_and_ethics.data+' '+J.author_workflow.references],['Revision, rights and sharing',J.author_workflow.revision+' '+J.access_and_rights.licence]].map(([t,p])=>details(t,`<p>${e(p)}</p>${link('Read the complete author guide',ref('03'))}`)).join('')}</div><div class="actions">${button('Read the complete guide',ref('03'))}${button('Download Guide for Authors','documents/'+doc('03').filename,true)}</div></section>`}
function review(){const r=G.reviewer_page;return pageTop('Review & ethics','Rigour suited to the contribution.',r.intro)+`<section class="wrap">${heading('Assessment routes','Different questions. Clear review labels.')} ${table(['Contribution','Assessment','Central question'],r.routes.map(x=>[x.type,x.route,x.question]))}<p class="small muted">${e(r.anonymity_note)}</p>${source('04','intro','Reviewer Guide · Routes and reviewer assignments')}</section><section class="pale"><div class="wrap">${heading('The proposed editorial journey','From receipt to a responsible release.','The timing below is an internal planning target, subject to adoption and capacity testing. It is not actual performance or a guarantee.')}<div class="flow">${r.workflow.map((x,i)=>`<div class="flow-item"><span class="step-num">${String(i+1).padStart(2,'0')}</span><h3>${e(x.stage)}</h3><p>${e(x.control)}</p><small>${e(x.owner)}</small><p style="margin-top:10px;color:var(--ink)">${e(x.proposed_target)}</p></div>`).join('')}</div>${source('04','Editorial workflow')}</div></section><section class="wrap split"><div><span class="eyebrow">A reasoned assessment</span><h2>Evidence over<br>a passing score.</h2><p class="muted">${e(r.assessment.rule)}</p><div class="tag-row">${r.assessment.ratings.map(x=>`<span class="tag">${e(x)}</span>`).join('')}</div>${source('07','T07')}</div><div>${r.assessment.dimensions.map(x=>`<div class="candidate"><h4>${e(x.dimension)}</h4><p>${e(x.prompt)}</p></div>`).join('')}</div></section><section class="wrap" style="padding-top:0">${heading('What an editorial decision means','Progress is not acceptance.')}<div class="accordion">${r.decisions.map(x=>details(x.decision,`<p>${e(x.meaning)}</p>`)).join('')}</div>${notice('Independent handling',G.journal_governance.independence_copy,'soft')}<div class="grid two"><div><h3>Before accepting a review</h3>${list(r.before_accepting)}<p style="margin-top:20px;font-size:14px">${e(r.confidentiality)}</p></div><div><h3>Appeals and the record</h3><p class="small">A proposed appeal should identify a factual or procedural issue within 30 calendar days. A different independent handler assesses the concern. Proposed targets: acknowledge within 5 working days; aim to resolve within 30 calendar days; update every 20 working days if delayed.</p><p class="small">Official appeal and integrity contacts will be published before submissions open. Corrections, concerns and retractions require a reasoned process and linked records.</p>${link('Read the complete editorial procedure',ref('04'))}</div></div></section>`}
function publications(){return pageTop('Articles & collections','The publication programme is taking shape.','PRAPJ proposes rolling digital publication and two curated collections each year. Publication dates will be announced after confirmation.')+`<section class="wrap"><div class="empty"><span class="eyebrow">Current publication status</span><h3>No PRAPJ articles have been published.</h3><p>Accepted work will appear after review, production and publication checks are complete. No citation metrics, indexing claims or publication history are available.</p></div><div style="margin-top:40px" class="grid two"><div><h2>The Research Summary Series</h2><p>${e(J.research_summary_series.copy)}</p><p class="small muted">No PRAPJ briefs have been published yet. Translation review will be labelled separately from independent research peer review.</p>${link('Explore the proposed brief format','#/authors/brief')}</div><div class="specimen-sheet"><span class="eyebrow">Separate design gallery</span><h3>See what the journal could look like.</h3><p>Explore four labelled design specimens and the editable hardcopy layout. These are demonstrations, not accepted publications.</p>${button('Explore the journal design','#/specimen')}</div></div>${source('06','Articles collections')}</section>`}
function templates(group='All'){const items=G.template_library.items.filter(x=>group==='All'||x.group===group);return pageTop('Resource library · 14 working forms','Less blank-page uncertainty.',G.template_library.intro)+`<section class="wrap"><div class="tabs" aria-label="Filter templates">${['All','Author preparation','Editorial operations','Supported contribution','Governance'].map(x=>`<button data-template-group="${e(x)}" aria-pressed="${group===x}">${e(x)}</button>`).join('')}</div><p class="small muted">${items.length} templates shown. Open each form in the source reader, or download the complete editable Word kit.</p><div class="template-grid">${items.map(x=>`<article class="template-card"><span class="template-code">${x.id} / ${e(x.group)}</span><h3>${e(x.title)}</h3><p>${e(x.use)}</p><span class="badge">${e(x.handling)}</span>${link('Open template',ref('07',x.id))}</article>`).join('')}</div>${notice('Keep completed private records private','The site supplies blank forms only. Consent evidence, author identities, reviewer identities and private correspondence belong in the future host’s restricted systems. No form on this site collects those records.','soft')}<div class="actions">${button('Download the complete kit','documents/'+doc('07').filename)}${button('Open the proposed author guide','#/authors',true)}</div></section>`}
function specimen(){return pageTop('Project review · Journal design','Make the publishing experience tangible.','Explore the pre-publication cover and four short design specimens from the editable print mockup. Physical print proof remains pending.')+`<section class="wrap specimen-layout"><img src="assets/journal-cover.png" alt="PRAPJ pre-publication cover concept"><div><span class="eyebrow">The publication is the experience</span><h2>Decision. Evidence.<br>Meaning. Limits.</h2><p class="lead">A journal page should help readers find each of these quickly.</p><p class="muted">The Word specimen demonstrates an editorial, a practitioner case, a research brief and a practice challenge. It does not contain accepted journal articles.</p>${notice('Design specimens only',J.specimen_gallery.persistent_notice)}<div class="actions">${button('Download print specimen','documents/'+doc('08').filename)}${button('Read complete specimen',ref('08'),true)}</div></div></section><section class="pale"><div class="wrap">${heading('Explore the design examples','Four ways to organise a contribution.')}<div class="grid two">${J.specimen_gallery.records.map((x,i)=>`<article class="specimen-sheet"><div class="sample-line">0${i+1} · ${e(x.format)}</div><h2>${e(x.title)}</h2><span class="badge pending">${e(x.status)}</span><p style="margin-top:20px">${e(x.description)}</p>${link('Read the specimen',ref('08',x.title))}</article>`).join('')}</div></div></section><section class="wrap">${heading('A practitioner-case example','What would count as evidence?','The stage-gate case is fictional. This table shows what a real contribution would need; it reports no measured outcome.')} ${table(['Question','Evidence needed','Cannot infer'],J.specimen_gallery.records[1].evidence_table.map(x=>[x.question,x.evidence_needed,x.cannot_infer]))}${source('08','Case evidence')}</section>`}
function project(){return pageTop('Project review · Team DOMINUS','The case for a journal worth establishing.','PRAPJ brings the publication proposition, editorial governance and practical tools into one reviewable package. The ambition is formal publication; the current work prepares the decisions and conditions needed to get there.',`<div class="actions">${button('Examine the business case','#/case')}${button('Explore the deliverables','#/delivery',true)}</div>`)+`<section class="wrap"><div class="kpi-grid"><div class="kpi"><span class="value">4 / 4</span><span class="label">Stakeholder interviews completed</span></div><div class="kpi"><span class="value">7</span><span class="label">Journal comparators examined</span></div><div class="kpi"><span class="value">3</span><span class="label">Success-measure areas</span></div><div class="kpi"><span class="value">8</span><span class="label">Source documents in this website</span></div></div>${notice('Current project status','Charter and PMP signed. The Business Case, governance documents, toolkit and mockups are prepared. Final deliverable acceptance, physical print proof and schedule verification remain pending.','soft')}<div class="grid three">${[['01','A persuasive case','Evidence, stakeholders, alternative delivery models and hypothetical resource scenarios.','#/case'],['02','Accountable governance','Separate Advisory and Editorial Boards, decision rights and prospective invitation pools.','#/governance'],['03','A tangible publication','Author and reviewer guidance, reusable templates, digital design and a print specimen.','#/specimen']].map(([n,t,p,u])=>`<a class="route-card" href="${u}"><span class="n">${n}</span><h3>${t}</h3><p>${p}</p><span class="card-bottom">Explore this outcome <span>↗</span></span></a>`).join('')}</div>${source('01','1. Mandate')}</section><section class="pale"><div class="wrap split"><div><span class="eyebrow">The proposed value</span><h2>A structured connection.<br>Not a claim of proven impact.</h2><p class="muted">The interviews and comparator analysis inform a design hypothesis: credible evidence is more useful when decisions, context and transfer limits are visible.</p></div><div class="steps"><div class="step"><div><h3>For readers</h3><p>Inspect evidence for professional judgement without losing important caveats.</p></div></div><div class="step"><div><h3>For contributors</h3><p>Find an appropriate route for research, documented practice or a focused question.</p></div></div><div class="step"><div><h3>For the sponsor</h3><p>Evaluate a publishing service with explicit roles, quality controls, resources and release gates.</p></div></div></div></div></section><section class="wrap">${heading('Prepared does not mean launched','The next decisions are operational.')}<div class="grid three">${[['Ownership','Confirm a continuing publisher, host and accountable operational owner.'],['Capacity','Confirm independent editors, reviewer capacity and supported workload.'],['Sustainability','Secure resources, adopt policies and validate the end-to-end publishing workflow.']].map(([t,p])=>`<div class="risk"><h3>${t}</h3><p>${p}</p></div>`).join('')}</div>${notice('No committed budget','The Capstone project has no approved or allocated budget. All financial estimates shown here are hypothetical; they are not quotes, actual expenditure or committed funding.')}</section>`}
const money=n=>new Intl.NumberFormat('en-AU',{style:'currency',currency:'AUD',maximumFractionDigits:0}).format(Number(n));
function optionChart(feasible=false){const o=B.option_appraisal,key=feasible?'feasibility_priority_total':'base_total',weights=feasible?o.feasibility_priority_weights_percent:o.base_weights_percent;return `<div class="bars" role="img" aria-label="Illustrative option scores out of 100">${o.options.map(x=>`<div class="bar-row"><span>${e(x.label)}</span><div class="bar-track"><div class="bar-fill ${x.id==='D'?'highlight':''}" style="width:${x[key]}%"></div></div><span class="bar-value">${x[key]}/100</span></div>`).join('')}</div><p class="small muted">${e(o.chart_caption)}</p><div class="tag-row">${o.criteria.map((x,i)=>`<span class="tag">${e(x)} · ${weights[i]}%</span>`).join('')}</div>`}
function financePanel(id='core_growth'){const f=B.financial_model,s=f.scenarios.find(x=>x.id===id),vals=s.cash_ceiling_exact_aud.map(Number),max=100000,w=760,h=285,base=225,topY=30;return `<div class="grid two"><div><span class="eyebrow">${e(s.label)} · hypothetical AUD</span><h3>Annual operating cash ceilings</h3><svg class="money-chart" viewBox="0 0 ${w} ${h}" role="img" aria-label="${e(s.label)}: ${vals.map((v,i)=>'Year '+(i+1)+' '+money(v)).join('; ')}">${[0,25000,50000,75000,100000].map(v=>{const y=base-v/max*(base-topY);return `<line x1="65" x2="745" y1="${y}" y2="${y}" stroke="#d8ddd4"/><text x="54" y="${y+4}" text-anchor="end">${v===0?'0':v/1000+'k'}</text>`}).join('')}${vals.map((v,i)=>{const x=122+i*205,bh=v/max*(base-topY);return `<rect x="${x}" y="${base-bh}" width="110" height="${bh}" fill="${['#23766c','#608778','#b58a35'][i]}" rx="2"/><text class="data-label" x="${x+55}" y="${base-bh-10}" text-anchor="middle">${money(v)}</text><text x="${x+55}" y="250" text-anchor="middle">Year ${i+1}</text><text x="${x+55}" y="272" text-anchor="middle">${s.planned_items[i]} planned items</text>`}).join('')}</svg><p class="small muted">Annual bars include 15% contingency and a 3% annual escalation assumption. Optional validation and media support are excluded.</p></div><div><div class="finance-cards" style="grid-template-columns:1fr"><div><span>Year 1 cash ceiling</span><strong>${money(vals[0])}</strong><span>${s.managing_editor_hours[0]} managing-editor hours</span></div><div><span>Three-year total including optional validation</span><strong>${money(s.three_year_with_optional_paid_validation_exact_aud)}</strong><span>Includes one hypothetical ${money(f.optional_paid_validation.amount)} validation allowance</span></div></div><p class="small muted" style="margin-top:20px">${e(f.year_definition)} ${e(f.scenario_caption)}</p>${details('Inspect the arithmetic',`<p>Annual ceiling = (managing-editor hours × hourly rate + items × production rate + annual services) × 1.03<sup>year−1</sup> × 1.15.</p>${table(['Input','This scenario'],[['Base hourly rate',money(s.base_hourly_rate_aud)],['Base production unit',money(s.base_production_unit_aud)],['Base annual services',money(s.base_annual_services_aud)],['Managing-editor hours by year',s.managing_editor_hours.join(' / ')],['Planned items by year',s.planned_items.join(' / ')]])}<p>Totals are calculated before rounding; summing displayed annual figures can differ by $1.</p>`)}</div></div>`}
function cashChart(){const rows=B.financial_model.monthly_cash.rows,x=i=>60+i*59,y=v=>235-v/22000*200,points=k=>rows.map((r,i)=>`${x(i)},${y(r[k])}`).join(' ');return `<svg class="trend-svg" viewBox="0 0 750 300" role="img" aria-label="Hypothetical cash timing: delaying the second receipt from month 7 to month 10 produces a 450 dollar cash shortfall at month 9.">${[0,5000,10000,15000,20000].map(v=>`<line x1="55" x2="725" y1="${y(v)}" y2="${y(v)}" stroke="#d8ddd4"/><text x="46" y="${y(v)+4}" text-anchor="end">${v/1000}k</text>`).join('')}<polyline points="${points('closing_cash_receipt_month7_aud')}" fill="none" stroke="#23766c" stroke-width="3"/><polyline points="${points('closing_cash_receipt_month10_aud')}" fill="none" stroke="#b58a35" stroke-width="3" stroke-dasharray="6 4"/>${rows.map((r,i)=>`<text x="${x(i)}" y="274" text-anchor="middle">M${i+1}</text>`).join('')}<circle cx="${x(8)}" cy="${y(-450)}" r="5" fill="#cd6549"/><text x="${x(8)+12}" y="${y(-450)+4}">−$450</text></svg>`}
function casePage(){const f=B.financial_model;return pageTop('Project review · Business case','A publication model with a clear purpose.','The case recommends a dedicated journal that connects research, documented practice and professional decisions. Its viability depends on operational ownership, independent assessment, reader value and sustainable resources.',`<div class="actions">${button('Read the complete Business Case',ref('01'))}${button('Download Word document','documents/'+doc('01').filename,true)}</div>`)+`<section class="wrap">${heading('01 / Evidence behind the design','Four conversations. Complementary perspectives.',B.interview_evidence.description)}<div class="timeline">${B.interview_evidence.records.map(x=>`<div class="event"><time datetime="${x.date}">${new Date(x.date+'T12:00:00').toLocaleDateString('en-GB',{day:'numeric',month:'short'})} 2026</time><h3>${e(x.name)}</h3><p>${e(x.insight)}</p></div>`).join('')}</div><div class="accordion">${B.interview_evidence.records.map(x=>details(x.name+' · design response and evidence boundary',`<p><strong>Design response:</strong> ${e(x.design_response)}</p><p><strong>Evidence boundary:</strong> ${e(x.evidence_limit)}</p>`)).join('')}</div>${source('01','2. Interview')}</section><section class="pale"><div class="wrap">${heading('02 / A demanding competitive landscape','A bridge already exists. Execution must matter.',B.comparators.intro)}${table(['Comparator','Position described in the Business Case','Implication for PRAPJ'],B.comparators.rows.map(x=>[x.name,x.observed_position,x.implication]))}<p class="small muted">${e(B.comparators.unknown_rule)} Descriptions reflect the supplied Business Case; current service details have not been independently refreshed for this website.</p>${source('01','3. Research')}</div></section><section class="wrap">${heading('03 / Alternatives and trade-offs','Why a dedicated journal — and under what conditions?',B.option_appraisal.copy)}<div class="tabs" aria-label="Option appraisal weights"><button data-weights="base" aria-pressed="true">Base priorities</button><button data-weights="feasibility" aria-pressed="false">More weight on feasibility</button></div><div id="option-chart">${optionChart()}</div>${notice('A close decision, not a proof',B.option_appraisal.sensitivity,'soft')}<div class="accordion">${details('Inspect the scoring method',`<p>Scores are analyst judgements from 1 to 5. Weighted total = Σ(score ÷ 5 × criterion weight), out of 100.</p>${table(['Option',...B.option_appraisal.criteria],B.option_appraisal.options.map(x=>[x.label,...x.scores]))}`)}${B.option_appraisal.options.map(x=>details(x.label,`<p>${e(x.copy)}</p>`)).join('')}</div>${source('01','5. Strategic')}</section><section class="pale"><div class="wrap">${heading('04 / Hypothetical resources','A visible cost of doing the work.','No actual project budget is allocated or approved. No journal funding is committed. Every value in this section is a hypothetical planning assumption in AUD.')}<div class="tabs" aria-label="Financial scenario">${f.scenarios.map(x=>`<button data-scenario="${x.id}" aria-pressed="${x.id==='core_growth'}">${e(x.label)}</button>`).join('')}</div><div id="finance-panel">${financePanel()}</div>${source('01','7. Financial')}<div class="accordion" style="margin-top:35px">${details('What makes up the base year?',table(['Core cash component','Assumption','AUD'],f.core_components.map(x=>[x.name,x.formula,money(x.amount)]))+`<div class="finance-cards"><div><span>Planned cash</span><strong>${money(f.core_planned_cash)}</strong></div><div><span>15% contingency</span><strong>${money(f.core_contingency)}</strong></div><div><span>Cash ceiling</span><strong>${money(f.core_cash_ceiling)}</strong></div></div>`)}${details('Cash is only part of the resource requirement',`<p>The model also assumes <strong>354 hours of contributed expertise</strong>, valued at AUD 90/hour for replacement-cost analysis: <strong>${money(f.contributed_expertise.replacement_value)}</strong>. These are not confirmed donated hours or fees offered.</p><p>The base resource envelope including cash contingency is ${money(f.contributed_expertise.resource_envelope_including_cash_contingency)}. It is not an actual budget.</p>${list(f.excluded_or_unpriced)}`)}${details('Optional interview support and media',`<p>A separate extension assumes six supported conversations at three hours each and four media items at six hours each: 42 additional hours × AUD 55 × 1.15 = <strong>AUD 2,656.50</strong>.</p><p>The core plus extension would be AUD 40,261.50. Add only work outside the existing allowances and remove overlaps before applying contingency. These amounts are excluded from the displayed three-year scenarios.</p>`)}${details('Cash timing can constrain a solvent-looking plan',`<p>Illustrative receipts: AUD 25,000 in operating month 1 and AUD 12,605 in month 7. Delaying the second receipt to month 10 creates a month-9 shortfall of AUD 450.</p><div class="legend"><span>Second receipt in M7</span><span>Second receipt delayed to M10</span></div>${cashChart()}<p class="small">No receipts are committed. Contingency is not spent in this schedule. AUD 5,355 of bridging liquidity would preserve the full AUD 4,905 contingency at the low point.</p>${table(['Month','Planned cost','Closing cash: M7 receipt','Closing cash: M10 receipt'],f.monthly_cash.rows.map(x=>['M'+x.operating_month,money(x.planned_cost_aud),money(x.closing_cash_receipt_month7_aud),money(x.closing_cash_receipt_month10_aud)]))}`)}</div></div></section><section class="wrap split"><div><span class="eyebrow">05 / Quality needs capacity</span><h2>Publication growth creates review work.</h2><p class="muted">The base model assumes 16 published items, including four linked briefs. It is a workload model, not a recruited pipeline or output commitment.</p>${source('01','6. Operating')}</div><div>${table(['Planned output','Items'],B.publication_capacity.planned_core_items.map(x=>[x.type,x.count]))}<p class="small">Modelled research/case pipeline: <strong>24 received → 16 externally reviewed → 10 accepted</strong>. First and revision rounds require <strong>48 completed reports</strong>.</p><p class="small">A planning roster of <strong>25 reviewers</strong> reflects three accepted assignments per reviewer, 80% completion yield and 80% planned utilisation. Relevant expertise and independence must also be confirmed.</p></div></section>`}
function governance(){const g=G.journal_governance,p=G.project_review;return pageTop('Project review · Governance','Separate the mission from manuscript decisions.',g.intro)+`<section class="wrap"><div class="org-tree"><div class="org-tier">${g.boards.map(x=>`<div class="org-box"><span class="eyebrow">Proposed role</span><h3>${e(x.title)}</h3><p>${e(x.short_copy)}</p></div>`).join('')}</div><div class="arrowline">Strategic advice and resources → independent editorial responsibility</div><div class="org-box central"><h3>Editor-in-Chief or independent delegated editor</h3><p>Manuscript decisions are reasoned editorial decisions. Sponsors and board meetings do not decide ordinary acceptance.</p></div><div class="arrowline">Appropriate evidence + independent reports + clear decision record</div><div class="org-tier"><div class="org-box"><h3>Research & Practice Editors</h3><p>Assign expertise, assess evidence and manage reviews within written delegations.</p></div><div class="org-box"><h3>Translation Editor</h3><p>Check fidelity, practical meaning and limitations in briefs and optional media.</p></div><div class="org-box"><h3>Managing Editor</h3><p>Coordinate records, versions, rights, metadata and production.</p></div></div></div>${source('02','Editorial Board')}<div class="accordion">${g.boards.map(x=>details(x.title+' · composition, terms and meetings',`<p>${e(x.proposed_composition)}</p>${table(['Governance field','Proposed arrangement'],[['Terms',x.terms],['Meetings',x.meetings],['Quorum',x.quorum],['Decision rule',x.decision_rule]])}${list(x.responsibilities)}`)).join('')}${details('Conflict handling and appeals',list(g.independence_controls))}</div></section><section class="pale"><div class="wrap">${heading('Prospective invitation pool','Candidates for discussion, not appointed members.')} ${notice('Project-review material',p.disclosure)}<div class="grid two">${[['Advisory Board',p.advisory_candidates],['Editorial Board',p.editorial_candidates]].map(([title,people])=>`<div><h3>${title}</h3>${people.map(x=>`<div class="candidate"><h4>${e(x.name_as_source)} <span class="badge pending">Prospective</span></h4><p>${e(x.summary)}</p></div>`).join('')}</div>`).join('')}</div>${source('02','Prospective Advisory')}<div style="margin-top:30px">${link('Read the full shortlist and invitation sequence',ref('02'))}</div></div></section><section class="wrap">${heading('Before a name becomes a public appointment','Agreement, independence and an accurate profile.')}<div class="flow">${[['Confirm fit','Check the proposed role, current affiliation, expertise and capacity.'],['Declare interests','Assess conflicts and agree a workable independent-handling arrangement.'],['Record acceptance','Obtain written acceptance and approved profile wording before announcement.']].map(([t,p],i)=>`<div class="flow-item"><span class="step-num">0${i+1}</span><h3>${t}</h3><p>${p}</p></div>`).join('')}</div>${link('Open T11 invitation and acceptance',ref('07','T11'))}</section>`}
function delivery(){return pageTop('Project review · Delivery and risk','Prepared outputs. Clear remaining decisions.','The signed Charter and PMP establish the planning basis. The prepared deliverables still require final acceptance; a physical print proof and schedule verification also remain pending.')+`<section class="wrap">${heading('The three success measures','What has been prepared.')} ${[['01','Business Case','A structured publication proposition, stakeholder evidence, comparator analysis, alternative options, operating model and hypothetical resources.','#/case'],['02','Governance package','Separate Advisory and Editorial Board Terms of Reference, decision rights and prospective candidate shortlists.','#/governance'],['03','Guidelines, templates and mockups','Author and reviewer guidance, 14 forms, website copy, a digital design and editable print specimen.','#/templates']].map(([n,t,p,u])=>`<div class="deliverable"><span class="n">${n}</span><div><h3>${t}</h3><p>${p}</p>${link('Explore the prepared work',u)}</div><span class="badge">Prepared · acceptance pending</span></div>`).join('')}${source('01','9. Delivery')}<div class="grid two" style="margin-top:35px"><div><h3>Remaining capstone work</h3>${list(B.roadmap.capstone_next_steps)}</div><div class="notice soft"><strong>20 November 2026 · Capstone deadline</strong>Four interviews are complete. No further capstone interviews are planned. Future reader or contributor validation belongs to journal development, not an assumed completed project activity.</div></div></section><section class="pale"><div class="wrap">${heading('Publication-readiness gates','A controlled path to opening submissions.','These are proposed future decisions. Six- and twelve-month reviews are measured from journal operation, not calendar dates.')}<div class="flow">${B.roadmap.gates.map(x=>`<div class="flow-item"><span class="step-num">${x.id}</span><h3>${e(x.label)}</h3><p>${e(x.required_evidence)}</p><small>${e(x.authority)} · ${e(x.status)}</small></div>`).join('')}</div>${source('01','8. Publication')}</div></section><section class="wrap">${heading('Risk and resilience','Monitor triggers. Adjust commitments.','The controls below are proposals. They are not evidence that these risks occurred or were successfully mitigated.')}<div class="grid two">${B.risks.register.filter(x=>B.risks.featured.includes(x.risk)).map(x=>`<div class="risk"><span class="eyebrow">Accountable: ${e(x.accountable_role)}</span><h3>${e(x.risk)}</h3><p><strong>Trigger:</strong> ${e(x.trigger)}</p><p class="control"><strong>Proposed response:</strong> ${e(x.proposed_control)}</p></div>`).join('')}</div><div class="accordion" style="margin-top:28px">${details('Explore the complete risk register',table(['Risk','Priority','Trigger','Proposed control','Accountable role'],B.risks.register.map(x=>[x.risk,x.priority,x.trigger,x.proposed_control,x.accountable_role])))}</div>${source('01','10. Risk')}</section>`}
function handoff(){return pageTop('Project review · Website content handoff','A readable service, built on governed content.','This site makes the supplied material easier to explore. A production journal still needs confirmed ownership, adopted terms, secure workflows and an authorised opening of submissions.')+`<section class="wrap">${heading('The information architecture','Two entrances. A shared evidence base.')}<div class="sitemap"><div><h3>The journal</h3>${journalNav.map(([id,n])=>`<a href="#/${id}">${e(n)} ↗</a>`).join('')}</div><div><h3>Project review</h3>${projectNav.map(([id,n])=>`<a href="#/${id}">${e(n)} ↗</a>`).join('')}</div><div><h3>Source library</h3>${D.map(d=>`<a href="${ref(d.id)}">${d.id} · ${e(d.title)} ↗</a>`).join('')}</div></div>${notice('Navigation is not access control','This public project showcase includes the journal concept, complete source library and prospective candidate discussion. The two reading modes organise the content; they do not restrict access.','blue')}</section><section class="pale"><div class="wrap">${heading('Function and release map','What is available now — and what comes later.')}<div class="accordion">${J.function_states.map(x=>details(x.function,`<p><strong>Current presentation:</strong> ${e(x.current)}</p><p><strong>Release condition:</strong> ${e(x.live_gate)}</p>`)).join('')}</div>${source('06','Publish and submission')}</div></section><section class="wrap">${heading('Content ownership','A release needs an accountable decision.')} ${table(['Content','Proposed approver','Before release'],[['Home and identity','Sponsor + founding Editor-in-Chief','Confirm name and development status'],['Scope and contribution formats','Editor-in-Chief','Reconcile taxonomy and exact limits with author guide'],['Board profiles','Appointing publisher + individual','Written acceptance and approved profile'],['Fees, licence and agreement','Host or publisher','Adopt terms and confirm support'],['Review, appeals and integrity','Editor-in-Chief + independent handler','Appoint roles and contact routes'],['Privacy, contact and accessibility','Host + website owner','Confirm actual entity and service arrangements']])}${source('06','intro','Website Content Handoff · Content ownership and release')}<div class="actions">${button('Read the complete handoff',ref('06'))}${button('Download the handoff','documents/'+doc('06').filename,true)}</div></section>`}
function library(){return pageTop('Source library · 8 supplied documents','The full detail, when you need it.','Start with the visual guides, then inspect the source. Each document is available as a section-by-section reader and as the original editable Word file.',`<div class="actions"><button class="button" data-search>Search all source text <span>⌕</span></button></div>`)+`<section class="wrap"><div class="library-grid">${D.map((d,i)=>`<article class="doc-card"><span class="doc-number">${d.id}</span><div><h3>${e(d.title)}</h3><p>${descriptions[i]}</p><span class="small muted">${d.sections.length} reading sections · DOCX source</span><div class="actions">${link('Read on this site',ref(d.id))}<a class="text-link" href="documents/${encodeURIComponent(d.filename)}" download>Download Word ↓</a></div></div></article>`).join('')}</div>${notice('Source and status','The reader preserves source wording, including internal notes, drafting instructions and provisional policies. Those are document content, not evidence of launch approval. Latest confirmed project status: final acceptance, physical proof and schedule verification are pending.','soft')}</section>`}
function sourceBlock(b){if(b.type==='table')return table(b.rows[0]||[],b.rows.slice(1));if(b.type==='image')return `<figure class="source-figure"><img loading="lazy" src="${e(b.src)}" alt="${e(b.alt)}"><figcaption>Original source-document figure. Read the surrounding source text for context.</figcaption></figure>`;const t=e(b.text);if(b.style==='Heading 2')return `<h3>${t}</h3>`;if(b.style==='Title')return `<h3>${t}</h3>`;return `<p class="${/List/.test(b.style)?'source-bullet':''}">${t}</p>`}
function reader(id,section){const d=doc(id);if(!d)return notFound();return pageTop('Full source reader · Document '+id,d.title,'Read the source in expandable sections. This view preserves the supplied wording; use the original Word download for the complete document layout.',`<div class="actions">${button('Download original Word file','documents/'+d.filename)}${button('Back to library','#/library',true)}</div>`)+`<section class="wrap reader"><aside class="reader-toc" aria-label="Document contents"><span class="eyebrow">On this document</span>${d.sections.map(s=>`<a href="#/document/${id}/${s.id}">${e(s.title)}</a>`).join('')}</aside><div class="reader-content"><div class="reader-tools"><button data-expand>Expand all</button><button data-collapse>Collapse all</button></div>${d.sections.map(s=>`<details class="reader-section" id="${s.id}" ${(section===s.id||!section&&s.id==='intro')?'open':''}><summary>${e(s.title)}</summary><div class="detail-body">${s.blocks.map(sourceBlock).join('')}</div></details>`).join('')}</div></section>`}
function notFound(){return pageTop('Page not found','Let’s get back to the journal.','The requested page or document is not available.',button('Return to overview','#/journal'))}
let lastPage='';
function render(){let parts=decodeURIComponent(location.hash||'#/journal').replace(/^#\//,'').split('/'),[page,arg,section]=parts;const preserve=(page===lastPage&&['authors','templates'].includes(page));if(projectNav.some(x=>x[0]===page)||page==='document'&&['01','02','06','08'].includes(arg))activeMode='project';else if(journalNav.some(x=>x[0]===page))activeMode='journal';$('.mode-switch a[data-mode="journal"]').classList.toggle('active',activeMode==='journal');$('.mode-switch a[data-mode="project"]').classList.toggle('active',activeMode==='project');$('#section-nav').innerHTML=(activeMode==='journal'?journalNav:projectNav).map(([id,label])=>`<a href="#/${id}" class="${id===page?'active':''}" ${id===page?'aria-current="page"':''}>${label}</a>`).join('');const pages={journal:home,about,authors:()=>authorPage(arg),review,publications,templates:()=>templates(arg||'All'),project,case:casePage,governance,delivery,specimen,handoff,library,document:()=>reader(arg,section)};$('#main').innerHTML=(pages[page]||notFound)();document.title=($('.page-top h1')?.textContent||'Evidence for project decisions')+' | PRAPJ';lastPage=page;if(page==='document'&&section){requestAnimationFrame(()=>document.getElementById(section)?.scrollIntoView({behavior:'instant',block:'start'}));}else if(!preserve)window.scrollTo({top:0,behavior:'instant'});}
window.addEventListener('hashchange',render);
document.addEventListener('click',ev=>{const el=ev.target.closest('button,a');if(!el)return;if(el.getAttribute('href')==='#main'){ev.preventDefault();$('#main').focus({preventScroll:true});$('#main').scrollIntoView({block:'start'});return;}if(el.hasAttribute('data-search')){openSearch();}if(el.hasAttribute('data-close-search'))$('#search-dialog').close();if(el.dataset.format)location.hash='/authors/'+el.dataset.format;if(el.dataset.templateGroup)location.hash='/templates/'+encodeURIComponent(el.dataset.templateGroup);if(el.dataset.weights){$$('[data-weights]').forEach(b=>b.setAttribute('aria-pressed',String(b===el)));$('#option-chart').innerHTML=optionChart(el.dataset.weights==='feasibility');}if(el.dataset.scenario){$$('[data-scenario]').forEach(b=>b.setAttribute('aria-pressed',String(b===el)));$('#finance-panel').innerHTML=financePanel(el.dataset.scenario);}if(el.hasAttribute('data-reset-checks')){$$('[data-check]').forEach(c=>c.checked=false);updateChecks();}if(el.hasAttribute('data-expand'))$$('.reader-section').forEach(d=>d.open=true);if(el.hasAttribute('data-collapse'))$$('.reader-section').forEach(d=>d.open=false);if(el.classList.contains('result'))$('#search-dialog').close();});
document.addEventListener('change',ev=>{if(ev.target.hasAttribute('data-check'))updateChecks();});
function updateChecks(){const items=$$('[data-check]'),n=items.filter(x=>x.checked).length;$('#check-count').textContent=`${n} of ${items.length} checked`;$('#check-fill').style.width=(n/items.length*100)+'%';}
const searchIndex=D.flatMap(d=>d.sections.map(s=>({doc:d.id,title:d.title,section:s.title,id:s.id,text:s.blocks.map(b=>b.type==='text'?b.text:b.type==='table'?b.rows.flat().join(' '):'').join(' ')})));
function openSearch(){$('#search-dialog').showModal();setTimeout(()=>$('#search-input').focus(),0);}
function search(){const q=$('#search-input').value.trim(),terms=q.toLowerCase().split(/\s+/).filter(Boolean);if(q.length<2){$('#search-status').textContent='Enter at least two characters. Search includes project-review material.';$('#search-results').innerHTML='';return;}const results=searchIndex.filter(x=>terms.every(t=>(x.title+' '+x.section+' '+x.text).toLowerCase().includes(t))).sort((a,b)=>Number(b.section.toLowerCase().includes(q.toLowerCase()))-Number(a.section.toLowerCase().includes(q.toLowerCase())));$('#search-status').textContent=`${results.length} matching sections${results.length>30?' · showing the first 30':''}.`;$('#search-results').innerHTML=results.slice(0,30).map(x=>{let at=x.text.toLowerCase().indexOf(terms[0]),start=Math.max(0,at-65),snippet=(start?'…':'')+x.text.slice(start,start+240)+'…';return `<a class="result" href="#/document/${x.doc}/${x.id}"><span>${e(x.title)}</span><strong>${e(x.section)}</strong><p>${e(snippet)}</p></a>`}).join('')||'<div class="empty"><h3>No matching sections</h3><p>Try a broader term, such as “evidence”, “review” or “funding”.</p></div>';}
$('#search-input').addEventListener('input',search);document.addEventListener('keydown',ev=>{if(ev.key==='/'&&!['INPUT','TEXTAREA'].includes(document.activeElement.tagName)&&!$('#search-dialog').open){ev.preventDefault();openSearch();}});$('#search-dialog').addEventListener('click',ev=>{if(ev.target===$('#search-dialog')){const r=$('#search-dialog').getBoundingClientRect();if(ev.clientX<r.left||ev.clientX>r.right||ev.clientY<r.top||ev.clientY>r.bottom)$('#search-dialog').close();}});render();
